) AS (
  VALUES 
    (71::BIGINT, 'No explica a profundidad, y hay preguntas que responde de manera que a uno no le queda claro. Apóyese en el libro del curso, y haga práctica, si tiene chance vaya a hora de consulta. No da las respuestas de las prácticas, porque "revisa" en clase, pero es muy general.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'f798a1a3a58b303f9a276587281bc74a5a942df5a60169fbf4c9892bfd4a9bbb'::TEXT, ARRAY[1707]::BIGINT[]),
    (71::BIGINT, 'Muy buen profe, la materia obvio es dura pero es responsabilidad de uno practicar y practicar hasta lograrlo, está siempre dispuesto a ayudar en horas de consulta cuando uno tiene una pregunta y la explica mil veces si es necesario. Muy buena persona'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2026-03-01T00:00:00+00:00'::TIMESTAMPTZ, 'da9647e0b930c7b54f2de7e13351a86d4e38f454eb1322f82cd2c7ce0fe25a0d'::TEXT, ARRAY[1707]::BIGINT[]),
    (71::BIGINT, 'Califica muy duro, no explica bien, sus clases son a pura presentación, no explica los temas con profundidad, su aprendizaje depende de si usted lee o no el capitulo que corresponde a la semana, las prácticas que hace de examen son totalmente diferentes a lo que viene en el examen'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2026-01-07T00:00:00+00:00'::TIMESTAMPTZ, 'd392c648f6bbf0f74d56ee3385808bd0b2cf4b637d9987b82e6ab6df1b254184'::TEXT, ARRAY[1707]::BIGINT[]),
    (71::BIGINT, 'Terrible, ojalá lo quitaran, no sé como es posible que el TEC admita profesores con tan bajo nivel. Cero nivel de enseñanza. NO matriculen con él.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '5f79cb6f78f2d49818daf30c074a5f6e2c68a2d1cdd240a0317271cc03023738'::TEXT, ARRAY[1707]::BIGINT[]),
    (71::BIGINT, 'No enseña, te sienta en clases a hacer prácticas y después "explica" la mitad de la práctica, deja muchas confusiones y no es claro con la materia. Para el último examen no explico nada de la materia, nada mas decía que leyeramos el libro. PESIMO PROFESOR.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2025-11-21T00:00:00+00:00'::TIMESTAMPTZ, '5354a40200a2645c383bb32c4b8a2f212214c6a672e808be4065d2d23b11becb'::TEXT, ARRAY[1707]::BIGINT[]),
    (71::BIGINT, 'Es un señor prepotente, nada que ver, todos fuimos estudiantes en algun momento,nose porque se cree la gran cosa y mas que es coordinador y para peores de TFG'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2024-03-13T00:00:00+00:00'::TIMESTAMPTZ, '0eece6ee6e4efe4d5074a2abcca03217845746b821482ff3df3c55175ae5ef89'::TEXT, ARRAY[2475]::BIGINT[]),
    (71::BIGINT, 'Es un pésimo profe, se cree muy interesante pero no ayuda en nada a los estudiantes'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-07-23T00:00:00+00:00'::TIMESTAMPTZ, '213634aa136995c0858f9ba7a2399feeb9c5b05c80f1f12fe41b5e0fd7c7c905'::TEXT, ARRAY[2394, 2366, 2361, 1707, 2429, 2426, 2947, 2395, 2946, 2367, 2362, 2358]::BIGINT[]),
    (71::BIGINT, 'Como persona muy buena gente pero como profesor muy malo, no tiene bases pedagógicas y que se dedique ser profesor tiempo completo y no hacer dos cosas al mismo tiempo como profesor y director de un departamento a la vez.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, '0f55fbcfc6a69aba7850aa3a021761030c184908c9fc331fe1a591766e2e2c40'::TEXT, ARRAY[2362]::BIGINT[]),
    (71::BIGINT, 'El modo virtual fue muy complicado, se exigió un nivel de práctica y rapidez con el excel alto y el profesor no brindo ningún tipo de apoyo o consideración con este tema, el cual no estaba dentro de los requisitos de la materia. Clases largas y exámenes más largos. Gran persona y trata de ayudar.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '35646ca9388b6a019c84176b007b8323b295a214de3159fd867f786caf4e178f'::TEXT, ARRAY[2362]::BIGINT[]),
    (71::BIGINT, 'Las clases son aburridas y confusas. El examen y las clases no están muy relacionados. No había mucha claridad en las indicaciones del proyecto, tareas, etc. Sin embargo, no es muy rudo calificando, comprende que muchas veces las cosas que solicita no se pueden hacer.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '24cebf64214a3cde2bb62840af1e8aa0c6d1639aa23cf9a895b5efbf473d185f'::TEXT, ARRAY[2414]::BIGINT[]),
    (71::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, '54919d4013ffac83df807d0a4b26f71932887eeb4e74fa17b21039ed0bd17c54'::TEXT, ARRAY[2414]::BIGINT[]),
    (71::BIGINT, 'Poca adaptacion a la modalidad virtual, califica todas tareas hasta el final del curso, se enfoca mucho en otros temas y no en explicar bien y directamente lo que entra en el examen, mala distribucion de la materia en los examenes, muy buena gente pero como profe no lo recomiendo'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-12T00:00:00+00:00'::TIMESTAMPTZ, '8083bea91adcafc71a6cbea9e7c67e666efac9d209c6d30d7c90f58c359e29bc'::TEXT, ARRAY[2362]::BIGINT[]),
