    (71::BIGINT, 'Es muy buena persona, es accesible, y califica normal Lo único es que en la parte práctica le cuesta explicar y habla demasiado de otros temas'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-24T00:00:00+00:00'::TIMESTAMPTZ, '4c66d1e5b8a655480d413fa672345cbc22387c1b38e92e6fe8e0bed968104e0e'::TEXT, ARRAY[2361]::BIGINT[]),
