    (71::BIGINT, 'es una excelente persona pero no explica muy bien y califica un poco duro en los exámenes, sin embargo, ayuda un poco'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'a4dabab31e0d5fd087a30dd9192708ecb1daae0aabfd375c60b5268fbb8df295'::TEXT, ARRAY[2361]::BIGINT[]),
